APX.dz = {"country":{"name":"Algeria","tagline":"Once the world's biggest wine exporter, now a quiet producer of sun-baked reds from the hills of Oran and Médéa.","classification":"Seven quality zones (labelled AOG, appellation d'origine garantie) recognised by the ONCV, inherited from French VDQS designations: Coteaux de Mascara, Coteaux de Tlemcen, Monts du Tessalah, Dahra, Coteaux du Zaccar, Médéa and Aïn Bessem-Bouira."},"regions":[{"name":"Algérois (central Algeria)","slug":"algerois-central-algeria","tagline":"","ids":["dz-ain-bessem-bouira","dz-coteaux-du-zaccar","dz-medea"]},{"name":"Oranie (western Algeria)","slug":"oranie-western-algeria","tagline":"","ids":["dz-coteaux-de-mascara","dz-coteaux-de-tlemcen","dz-dahra","dz-monts-du-tessalah"]}],"items":{"dz-ain-bessem-bouira":{"name":"Aïn Bessem-Bouira","cat":"AOG","region":"Algérois (central Algeria)","created":"Colonial VDQS; ONCV quality zone","styles":["red","rose","white"],"grapes":"Carignan, Cinsault, Grenache, Alicante Bouschet, Syrah, Clairette","summary":"The plateau around Aïn Bessem and Bouira, south-east of Algiers, known for rosés. The plateau lies at 500 to 700 metres between the Djurdjura and the Bibans ranges, with cool nights that suit fresh rosés and light reds from Cinsault and Grenache.","rslug":"algerois-central-algeria"},"dz-coteaux-de-mascara":{"name":"Coteaux de Mascara","cat":"AOG","region":"Oranie (western Algeria)","created":"Colonial VDQS; ONCV quality zone","styles":["red","rose","white"],"grapes":"Carignan, Cinsault, Grenache, Alicante Bouschet, Syrah, Clairette","summary":"The most famous Algerian name, from the hills around Mascara in the west, whose heavy, dark reds were prized for blending in colonial times and are counted among the country's best today.","rslug":"oranie-western-algeria"},"dz-coteaux-de-tlemcen":{"name":"Coteaux de Tlemcen","cat":"AOG","region":"Oranie (western Algeria)","created":"Colonial VDQS; ONCV quality zone","styles":["red","rose","white"],"grapes":"Carignan, Cinsault, Grenache, Alicante Bouschet, Syrah, Clairette","summary":"Hills around the historic city of Tlemcen near the Moroccan border, at 600 to 900 metres; a source of the ONCV's Cuvée du Président blend. Higher altitude and more rain than the coastal plains give these wines more freshness than most Algerian reds.","rslug":"oranie-western-algeria"},"dz-coteaux-du-zaccar":{"name":"Coteaux du Zaccar","cat":"AOG","region":"Algérois (central Algeria)","created":"Colonial VDQS; ONCV quality zone","styles":["red","rose","white"],"grapes":"Carignan, Cinsault, Grenache, Alicante Bouschet, Syrah, Clairette","summary":"The slopes of Mount Zaccar around Miliana, south-west of Algiers. Mount Zaccar rises above the town of Miliana in the Chelif valley, and its slopes give some of the freshest reds and rosés of central Algeria. Like the other zones, it is a colonial VDQS name kept by the ONCV.","rslug":"algerois-central-algeria"},"dz-dahra":{"name":"Dahra","cat":"AOG","region":"Oranie (western Algeria)","created":"Colonial VDQS; ONCV quality zone","styles":["red","rose","white"],"grapes":"Carignan, Cinsault, Grenache, Alicante Bouschet, Syrah, Clairette","summary":"The coastal Dahra massif between Mostaganem and Ténès, with sea-cooled hillside vineyards; a component of the Cuvée du Président. The Dahra hills, between the Chelif river and the sea, were one of the largest colonial wine areas.","rslug":"oranie-western-algeria"},"dz-medea":{"name":"Médéa","cat":"AOG","region":"Algérois (central Algeria)","created":"Colonial VDQS; ONCV quality zone","styles":["red","rose","white"],"grapes":"Carignan, Cinsault, Grenache, Alicante Bouschet, Syrah, Clairette","summary":"High vineyards in the Tell Atlas around Médéa, up to about 1,200 metres, among the coolest in Algeria. Altitude makes Médéa one of the coolest Algerian zones, and its reds are among the most balanced the ONCV bottles. Médéa also supplies the Cuvée du Président blend.","rslug":"algerois-central-algeria"},"dz-monts-du-tessalah":{"name":"Monts du Tessalah","cat":"AOG","region":"Oranie (western Algeria)","created":"Colonial VDQS; ONCV quality zone","styles":["red","rose","white"],"grapes":"Carignan, Cinsault, Grenache, Alicante Bouschet, Syrah, Clairette","summary":"The Tessala mountains near Sidi Bel Abbès, south of Oran; reds and rosés. The hills sit just west of Sidi Bel Abbès in the heart of the old Oranie wine country, where colonial estates once made bulk wine for blending in southern France. Today the zone produces mainly Carignan and Cinsault reds.","rslug":"oranie-western-algeria"}}};
